import type { Proposal, WatchStatus, WatchType } from '../../common';

export interface ReasoningStep {
  type: 'query' | 'finding' | 'tool' | 'collaboration' | 'conclusion';
  label: string;
  detail?: string;
  source?: string;
  flyout?: {
    title: string;
    content: string;
    data?: Array<{ label: string; value: string }>;
    query?: string;
    results?: string;
  };
}

export interface Collaborator {
  watchType: 'watch_floor' | 'watch_officer' | 'dark_watch' | 'deep_watch';
  contribution: string;
}

export interface ActionResult {
  summary: string;
  steps: Array<{ action: string; status: 'done' | 'pending' | 'blocked'; detail?: string }>;
  timestamp?: string;
}

export interface EnrichedProposal extends Proposal {
  reasoningChain?: ReasoningStep[];
  collaborators?: Collaborator[];
  actionResult?: ActionResult;
}

